from rom_v2.domain.story_content import V2StoryQuestContentRecord

STORY_DARK_FOREST_81_90 = (
    V2StoryQuestContentRecord('dark_forest_081_trace_beyond_the_stone_ravine', 81, 'Слід за кам’яним яром', 'TALK', 'dark_forest', 9, 'dark_forest_080_trace_of_the_runic_cult', 'mercenary_head', 'mercenary_head', 1, 'Голова Найманців отримав нові відомості про рух невідомих істот поблизу сьомої стоянки.', 'Отримати від Голови Найманців результати спостереження.', 'Після завершення операції розвідники залишилися спостерігати за сьомою стоянкою.\n\nГобліни майже не користуються основним проходом, але на протилежному боці кам’яного яру виявлено інші сліди. Вони ведуть до вузької стежки між корінням і скелями.\n\nСліди не схожі на сліди звичайних гоблінських дозорів. Невідомі проходили там неодноразово й намагалися приховати свій маршрут.', 'Голова Найманців показує на карті місце, де розвідники виявили приховану стежку.', 99, 4.13, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_082_hidden_path', 82, 'Прихована стежка', 'KILL_REGION', 'dark_forest', 9, 'dark_forest_081_trace_beyond_the_stone_ravine', 'mercenary_head', 'mercenary_head', 8, 'Озброєні загони перекривають підхід до прихованої стежки.', 'Перемогти 8 будь-яких істот у локації Темний Бір.', 'Розвідники спробували наблизитися до прихованої стежки, але вхід до неї перекритий.\n\nБіля кам’яної тріщини чергують озброєні загони. Вони не залишають своїх позицій навіть тоді, коли чують рух або бій осторонь.\n\nПереможи вісім ворогів біля позначеної ділянки. Не заходь за кам’яні схили. Зараз потрібно лише звільнити підхід.', 'Охорону біля кам’яної тріщини розбито. Підхід до прихованої стежки звільнено.', 99, 4.13, {'reward_formula': None, 'progress_text': 'Зачистка підходу до прихованої стежки: {progress}/8'}),
    V2StoryQuestContentRecord('dark_forest_083_land_without_tracks', 83, 'Земля без слідів', 'TALK', 'dark_forest', 9, 'dark_forest_082_hidden_path', 'mercenary_head', 'mercenary_head', 1, 'Розвідники оглянули початок прихованої стежки та помітили незвичайні зміни місцевості.', 'Отримати від Голови Найманців результати огляду прихованої стежки.', 'Після звільнення проходу розвідники змогли оглянути початок стежки.\n\nДалі звичайна лісова земля різко змінюється. Ґрунт стає темним і твердим, трава зникає, а коріння дерев виходить на поверхню.\n\nНа цій ділянці майже неможливо розрізнити сліди. Невідомо, чи зміни виникли природно, чи стали наслідком рунічного впливу.', 'Голова Найманців передає опис безплідної ділянки за прихованою стежкою.', 99, 4.13, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_084_dark_soil', 84, 'Темний ґрунт', 'QUEST_ITEM', 'dark_forest', 9, 'dark_forest_083_land_without_tracks', 'mercenary_head', 'mercenary_head', 1, 'Потрібно отримати матеріал із безплідної ділянки для подальшого дослідження.', 'Шукати під час полювання зразок матеріалу з безплідної ділянки.', 'Зовнішніх ознак недостатньо, щоб визначити природу змін.\n\nВізьми підготовлену посудину та знайди матеріал, який помітно відрізняється від звичайної землі Темного Бору.\n\nНе набирай попіл біля згаслих вогнищ або звичайну суху глину. Потрібен один зразок безпосередньо з безплідної ділянки.', 'Із безплідної ділянки зібрано й запечатано один зразок неприродно темного ґрунту.', 99, 4.13, {'reward_formula': None, 'quest_item': {'item_key': 'dark_forest_tainted_soil_sample', 'display_name': 'Зразок оскверненого ґрунту', 'quantity': 1, 'drop_chance': 0.15, 'drop_location_id': 'dark_forest', 'drop_message': '🧩 Сюжетна знахідка: Зразок оскверненого ґрунту'}, 'first_drop_text': 'Знайдений ґрунт має неприродно чорний колір. Між грудками видно тонкі синюваті прожилки, які слабко мерехтять у темряві.', 'progress_text': 'Пошук матеріалу з безплідної ділянки: {progress}/1', 'item_reveal_policy': {'pre_reveal_title': 'Темний ґрунт', 'post_reveal_title': 'Темний ґрунт', 'reveal_on_first_drop': True}, 'next_route': {'npc_id': 'alchemist', 'route_text': '🏙️ Місто → ⚒️ Ремісничий квартал → 🧪 Алхімік'}}),
    V2StoryQuestContentRecord('dark_forest_085_roots_of_corruption', 85, 'Коріння осквернення', 'TURN_IN', 'dark_forest', 9, 'dark_forest_084_dark_soil', 'alchemist', 'alchemist', 1, 'Передати Алхіміку запечатаний зразок зміненого ґрунту.', 'Передати Алхіміку зразок оскверненого ґрунту.', 'Постав посудину на кам’яну поверхню. Не відкривай її над дерев’яним столом.\n\nУ зразку є звичайні мінерали Темного Бору, але між ними накопичилася рунічна речовина.\n\nВона вже проникла в землю та зв’язалася з корінням рослин. Саме тому ґрунт потемнів, а трава на ділянці зникла.\n\nЗа одним зразком неможливо визначити розмір зміненої території.', 'Алхімік приймає зразок і підтверджує, що рунічна речовина проникла у ґрунт та коріння рослин.', 99, 4.13, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_tainted_soil_sample', 'quantity': 1, 'consume': True}]}),
    V2StoryQuestContentRecord('dark_forest_086_boundary_of_corruption', 86, 'Межа осквернення', 'TALK', 'dark_forest', 9, 'dark_forest_085_roots_of_corruption', 'alchemist', 'alchemist', 1, 'Алхімік підготував спосіб перевірки землі вздовж прихованої стежки.', 'Отримати від Алхіміка засіб для перевірки зміненого ґрунту.', 'Я підготував смужки обробленої тканини.\n\nБіля звичайної землі вони не змінюються. Якщо в ґрунті є та сама рунічна речовина, тканина поступово темніє.\n\nСмужки дадуть змогу перевірити землю без прямого контакту. Але використовувати їх потрібно обережно: бруд, попіл або кров можуть спотворити результат.', 'Алхімік передає оброблені смужки тканини та пояснює, як перевіряти ними землю.', 99, 4.13, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_087_through_black_roots', 87, 'Крізь чорне коріння', 'KILL_REGION', 'dark_forest', 9, 'dark_forest_086_boundary_of_corruption', 'alchemist', 'alchemist', 10, 'Озброєні загони не дозволяють провести перевірку ґрунту вздовж прихованої стежки.', 'Перемогти 10 будь-яких істот у локації Темний Бір.', 'Розвідники спробували встановити смужки, але далі стежку знову перекрили ворожі загони.\n\nПід час бою тканина легко забрудниться, тому спочатку потрібно звільнити ділянку.\n\nПереможи десять ворогів уздовж прихованої стежки. Не торкайся чорного коріння й не відходь від позначеного маршруту.', 'Охорону вздовж прихованої стежки послаблено. Ділянка біля чорного коріння стала доступною.', 99, 4.13, {'reward_formula': None, 'progress_text': 'Зачистка ділянки біля чорного коріння: {progress}/10'}),
    V2StoryQuestContentRecord('dark_forest_088_traces_among_the_roots', 88, 'Сліди серед коріння', 'QUEST_ITEM', 'dark_forest', 9, 'dark_forest_087_through_black_roots', 'alchemist', 'alchemist', 1, 'Перевірити територію біля чорного коріння та знайти предмет, який не міг з’явитися там природним шляхом.', 'Шукати під час полювання сторонній предмет біля чорного коріння.', 'Після зачистки розвідники змогли встановити смужки тканини. На одній ділянці вони темніють значно швидше.\n\nОглянь місцевість поблизу цього місця. Шукай будь-що, що не належить до природного середовища Темного Бору.\n\nНе відкривай футляри, згортки або посудини. Якщо на предметі є невідомі знаки, залиш його закритим.', 'Біля чорного коріння знайдено запечатаний футляр із невідомим документом.', 99, 4.13, {'reward_formula': None, 'quest_item': {'item_key': 'dark_forest_sealed_runic_order', 'display_name': 'Запечатаний рунічний наказ', 'quantity': 1, 'drop_chance': 0.15, 'drop_location_id': 'dark_forest', 'drop_message': '🧩 Сюжетна знахідка: Запечатаний рунічний наказ'}, 'first_drop_text': 'Між чорним корінням знайдено невеликий футляр. Усередині видно складений аркуш, запечатаний темним воском із рунічним символом.', 'progress_text': 'Пошук стороннього предмета: {progress}/1', 'item_reveal_policy': {'pre_reveal_title': 'Сліди серед коріння', 'post_reveal_title': 'Сліди серед коріння', 'reveal_on_first_drop': True}, 'next_route': {'npc_id': 'rune_master', 'route_text': '🏙️ Місто → ⚒️ Ремісничий квартал → 💠 Рунний Майстер'}}),
    V2StoryQuestContentRecord('dark_forest_089_seal_without_a_name', 89, 'Печатка без імені', 'TURN_IN', 'dark_forest', 9, 'dark_forest_088_traces_among_the_roots', 'rune_master', 'rune_master', 1, 'Передати Рунному Майстру запечатаний футляр для безпечного відкриття.', 'Передати Рунному Майстру запечатаний рунічний наказ.', 'Не ламай печатку. Навколо воску нанесено тонку руну, яка може пошкодити вміст футляра.\n\nЯ послаблю зовнішню лінію й відкрию його в захисному колі.\n\nУсередині справді міститься документ. Частину тексту записано умовними символами, а замість імені відправника використано рунічну печатку.\n\nЗі збереженого фрагмента зрозуміло лише те, що повідомлення призначалося охоронцям зміненої ділянки.', 'Рунний Майстер безпечно відкриває футляр і підтверджує, що всередині міститься наказ із рунічною печаткою без особистого імені.', 99, 4.13, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_sealed_runic_order', 'quantity': 1, 'consume': True}], 'next_route': {'npc_id': 'elder', 'route_text': '🏙️ Місто → 🏛️ Ратуша → 🗣️ Староста'}}),
    V2StoryQuestContentRecord('dark_forest_090_corrupted_lands', 90, 'Осквернені землі', 'TURN_IN', 'dark_forest', 9, 'dark_forest_089_seal_without_a_name', 'elder', 'elder', 1, 'Доповісти Старості про змінену землю та запечатаний наказ.', 'Доповісти Старості про результати дослідження прихованої стежки.', 'Прихована стежка веде через землю, у яку проникла рунічна речовина.\n\nЦе вже не короткий слід окремого обряду. Вплив змінив ґрунт, коріння й рослини.\n\nЗнайдений наказ підтверджує, що хтось контролює цю ділянку та передає розпорядження її охоронцям. Ім’я відправника приховано, але рунічна печатка пов’язує документ із попередніми знахідками.\n\nОтже, діяльність культу не обмежується амулетами й обрядами. Його вплив уже проник у сам Темний Бір.', 'Староста приймає доповідь про приховану стежку та змінену землю.\n\nЗібрані докази підтверджують, що рунічний вплив поширився на ґрунт і рослини Темного Бору, а охорона змінених ділянок виконує письмові накази.\n\n✅ Розділ «Осквернені землі» завершено.', 99, 4.13, {'reward_formula': None, 'required_quest_items': [], 'itemless_turn_in_policy': {'enabled': True, 'purpose': 'final_report', 'button_text': '🗣️ Доповісти Старості'}, 'next_quest_preview': {'number': 91, 'unlock_level': 10}}),
)

def validate_story_dark_forest_81_90() -> None:
    quests=STORY_DARK_FOREST_81_90
    if len(quests)!=10 or [q.number for q in quests]!=list(range(81,91)): raise ValueError('invalid_package_identity')
    if len({q.quest_id for q in quests})!=10: raise ValueError('duplicate_quest_id')
    if quests[0].previous_quest_id!='dark_forest_080_trace_of_the_runic_cult': raise ValueError('invalid_story_bridge')
    for previous,current in zip(quests,quests[1:]):
        if current.previous_quest_id!=previous.quest_id: raise ValueError('invalid_predecessor_chain')
    for quest in quests:
        if quest.unlock_level!=9 or quest.location_id!='dark_forest': raise ValueError('invalid_level_or_location')
        if quest.reward_exp < 0 or quest.reward_gold < 0: raise ValueError('invalid_reward')

validate_story_dark_forest_81_90()
